SELECT trip_id
FROM pubcar_approval_process
WHERE user_id = #{currentUserId}
  AND table_type = 2000
  AND approval_status = #{approvalStatus}
  AND reviewer_role = #{reviewerRole}
  AND status_cd = '0'
ORDER BY create_time DESC

    limit #{page}, #{row}

SELECT COUNT(*) count
FROM pubcar_approval_process
WHERE user_id = #{currentUserId}
  AND table_type = 2000
  AND approval_status = #{approvalStatus}
  AND reviewer_role = #{reviewerRole}
  AND status_cd = '0'

SELECT 1
FROM pubcar_approval_process
WHERE trip_id = #{tripId}
  AND reviewer_role = 1
  AND community_id = #{communityId}
LIMIT 1

SELECT m.trip_id tripId, m.approval_status approvalStatus, m.reviewer_role reviewerRole
FROM pubcar_approval_process m
LEFT JOIN pubcar_trip t ON t.trip_id = m.trip_id
LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id
LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0'
LEFT JOIN u_org_staff_rel r ON r.staff_id = uu.user_id AND r.status_cd = '0'
LEFT JOIN u_org uo ON uo.org_id = r.org_id AND uo.status_cd = '0'
LEFT JOIN t_dict d ON d.status_cd = r.rel_cd AND d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd'
WHERE t.status_cd= '0' AND m.status_cd = '0' AND m.table_type = 1000
  AND m.user_id = #{currentUserId}

    AND m.approval_status = #{approvalStatus}


    and t.user_id = #{userId}


    and uu.name like concat('%',#{applicant},'%')


    and uu.tel like concat('%',#{tel},'%')


    and t.start like concat('%',#{start},'%')


    and t.destination like concat('%',#{destination},'%')


    and t.apply_num= #{applyNum}


    and t.is_urgent= #{isUrgent}


    and uo.org_name like concat('%',#{department},'%')


    and d.name like concat('%',#{position},'%')


    and n.trip_type = #{tripType}


    and t.trip_status= #{tripStatus}



     and t.start_time >= #{applyTimeStart}


     and t.end_time <= #{applyTimeEnd}


    and t.trip_id= #{tripId}


    and m.community_id= #{communityId}

ORDER BY t.create_time DESC

    limit #{page}, #{row}

SELECT DISTINCT m.trip_id tripId
FROM pubcar_approval_process m
LEFT JOIN pubcar_trip t ON t.trip_id = m.trip_id
LEFT JOIN pubcar_trip_car_num n ON n.trip_id = t.trip_id
LEFT JOIN u_user uu ON uu.user_id = t.user_id AND uu.status_cd = '0'
LEFT JOIN u_org_staff_rel r ON r.staff_id = uu.user_id AND r.status_cd = '0'
LEFT JOIN u_org uo ON uo.org_id = r.org_id AND uo.status_cd = '0'
LEFT JOIN t_dict d ON d.status_cd = r.rel_cd AND d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd'
WHERE t.status_cd= '0' AND m.status_cd = '0' AND m.table_type = 1000
AND m.user_id = #{currentUserId}

    AND m.approval_status = #{approvalStatus}


    and t.user_id = #{userId}


    and uu.name like concat('%',#{applicant},'%')


    and uu.tel like concat('%',#{tel},'%')


    and t.start like concat('%',#{start},'%')


    and t.destination like concat('%',#{destination},'%')


    and t.apply_num= #{applyNum}


    and t.is_urgent= #{isUrgent}


    and uo.org_name like concat('%',#{department},'%')


    and d.name like concat('%',#{position},'%')


    and n.trip_type = #{tripType}


    and t.trip_status= #{tripStatus}



     and t.start_time >= #{applyTimeStart}


     and t.end_time <= #{applyTimeEnd}


    and t.trip_id= #{tripId}


    and m.community_id= #{communityId}

