SELECT approval_process_id approvalProcessId, trip_id tripId, user_id userId, approval_status approvalStatus,
       reviewer_role reviewerRole, sequence, b_id bId, table_type tableType, community_id communityId, status_cd statusCd
FROM pubcar_approval_process
WHERE status_cd = #{statusCd}

    AND trip_id = #{tripId}


    AND reviewer_role = #{reviewerRole}


    AND b_id = #{bId}
